<?php
require_once __DIR__.'/../../auth/auth_check.php';require_once __DIR__.'/../../config/database.php';$error='';
if($_SERVER['REQUEST_METHOD']==='POST'){$judul=trim($_POST['judul']??'');$penulis=trim($_POST['penulis']??'');if($judul&&isset($_FILES['file'])&&$_FILES['file']['error']===UPLOAD_ERR_OK){$ext=strtolower(pathinfo($_FILES['file']['name'],PATHINFO_EXTENSION));if(in_array($ext,['pdf','doc','docx'],true)){ $name='ebook_'.time().'.'.$ext;$dir=__DIR__.'/../../uploads/dokumen';if(!is_dir($dir))mkdir($dir,0777,true);if(move_uploaded_file($_FILES['file']['tmp_name'],$dir.'/'.$name)){ $st=$pdo->prepare('INSERT INTO ebook (judul,penulis,deskripsi,nama_file) VALUES (?,?,?,?)');$st->execute([$judul,$penulis,$_POST['deskripsi']??'', $name]);header('Location: index.php');exit;}}else{$error='File harus PDF, DOC, atau DOCX.';}}else{$error='Judul dan file wajib diisi.';}}
?><!doctype html><html lang="id"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Ebook | SICERDAS</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet"><link href="https://cdnjs.cloudflare.com/ajax/libs/font-awesome/6.5.2/css/all.min.css" rel="stylesheet"><link href="../../assets/css/style.css" rel="stylesheet"></head><body><?php include __DIR__.'/../../layouts/sidebar.php';?><div class="main-wrapper"><?php include __DIR__.'/../../layouts/navbar.php';?><main class="content"><div class="page-heading"><div><p>Pustaka Sistem</p><h1>Ebook & Dokumen Panduan</h1></div></div><div class="row g-3"><div class="col-lg-4"><div class="panel p-3"><h2 class="fs-6">Unggah Dokumen</h2><?php if($error):?><div class="alert alert-danger"><?=htmlspecialchars($error)?></div><?php endif?><form method="post" enctype="multipart/form-data" class="vstack gap-2"><input class="form-control" name="judul" placeholder="Judul" required><input class="form-control" name="penulis" placeholder="Penulis"><textarea class="form-control" name="deskripsi" rows="2" placeholder="Deskripsi"></textarea><input type="file" class="form-control" name="file" accept=".pdf,.doc,.docx" required><button class="btn btn-orange">Unggah</button></form></div></div><div class="col-lg-8"><div class="panel table-panel"><div class="table-responsive"><table class="table sicerdas-table"><thead><tr><th>Judul</th><th>Penulis</th><th>Deskripsi</th><th>Aksi</th></tr></thead><tbody><?php foreach($pdo->query('SELECT * FROM ebook ORDER BY created_at DESC') as $r):?><tr><td><?=htmlspecialchars($r['judul'])?></td><td><?=htmlspecialchars($r['penulis'])?></td><td><?=htmlspecialchars($r['deskripsi'])?></td><td><a class="btn btn-sm btn-detail" target="_blank" href="../../uploads/dokumen/<?=urlencode($r['nama_file'])?>">Unduh</a></td></tr><?php endforeach?></tbody></table></div></div></div></div></main></div><script src="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/js/bootstrap.bundle.min.js"></script></body></html>
